const root=$('#app');
let token=getStoredAdminToken(), data={classes:[],students:[],materials:[],assignments:[],attempts:[],settings:{}}, view='dashboard', modalSubmit=null, wizard={step:0,classId:'',materialId:'',templateId:'quiz',title:'',instructions:'',timeLimit:0,attempts:0,shuffle:true,dueAt:'',status:'published'}, filterText='', reviewClass='', reviewStudent='', reviewStudentClass='all', toastTimer=null, liveTestState={materialId:'',templateId:'quiz'}, liveTestGame=null, liveTestReturn='live-test';
const nav=[['dashboard','space_dashboard','Dashboard'],['assign','assignment_turned_in','Assign Games'],['live-test','sports_esports','Live Test Game'],['game-builder','construction','Game Builder'],['classes','groups','Kelas'],['students','school','Siswa'],['materials','menu_book','Materi'],['question-bank','quiz','Question Bank'],['generator','auto_awesome','Generator Soal'],['class-review','leaderboard','Review Kelas'],['student-review','query_stats','Review Siswa'],['game-guide','menu_book','Panduan 34 Game'],['settings','settings','Settings']];

function loginView(){root.innerHTML=`<div class="login-screen"><form class="login-card card" id="login-form"><div class="brand-row"><div class="brand-mark">JEC</div><div><h1>ESL Game Hub</h1><p>Admin panel · Jagat Education Center</p></div></div><div class="login-art"><span>JEC GAME HUB</span></div><div class="eyebrow">Internal access</div><h2 style="margin:5px 0 4px;font-size:20px">Masuk sebagai Admin</h2><p class="muted" style="font-size:13px;margin:0 0 18px">Masukkan PIN admin untuk mengelola game dan siswa.</p><div class="field"><label>PIN Admin</label><input id="admin-pin" type="password" inputmode="numeric" autocomplete="current-password" placeholder="Masukkan PIN" required></div><button class="btn btn-primary" style="width:100%" type="submit">Masuk ${'<span class="material-symbols-rounded">arrow_forward</span>'}</button><div class="divider"></div><div class="small muted">Mode database: ${isRemote()?'Google Sheets terhubung':'Demo lokal browser'} · <a href="index.html" style="color:var(--green);font-weight:900">Panel siswa ↗</a></div></form></div>`;}
function shell(){root.innerHTML=`<div class="admin-shell"><aside class="sidebar" id="sidebar"><div class="sidebar-brand"><div class="brand-mark">JEC</div><div><strong>JEC ESL Game Hub</strong><small>ADMIN CONSOLE</small></div></div><div><div class="nav-label">WORKSPACE</div><nav class="side-nav">${nav.map(([id,ic,label])=>`<button class="side-link ${view===id?'active':''}" data-view="${id}">${iconHtml(ic)}<span>${label}</span></button>`).join('')}</nav></div><div class="sidebar-bottom"><div class="small" style="color:#9db9ab;margin-bottom:9px">Jagat Education Center</div><button class="side-link" data-action="logout">${iconHtml('logout')}<span>Keluar</span></button></div></aside><div class="mobile-overlay" id="mobile-overlay"></div><main class="admin-main"><header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-menu" data-action="menu">${iconHtml('menu')}</button><div><div class="topbar-title">${nav.find(x=>x[0]===view)?.[2]||'Dashboard'}</div><div class="topbar-meta">ESL Game Management · JEC Internal</div></div></div><div class="row"><span class="pill ${isRemote()?'':'warn'}">${isRemote()?'● Sheets connected':'● Demo mode'}</span><div class="avatar">AD</div></div></header><section class="admin-content" id="content"></section></main></div>`;renderView();}
function iconHtml(n){return `<span class="material-symbols-rounded">${esc(n)}</span>`;}
function stat(label,value,icon,sub=''){return `<div class="card stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${iconHtml(icon)}</span></div><div class="stat-value">${value}</div><div class="small muted">${sub}</div></div>`;}
function sectionHead(title,sub,action=''){return `<div class="section-head"><div><h1 class="page-title">${title}</h1><p class="page-subtitle">${sub}</p></div>${action}</div>`;}
function empty(text){return `<div class="empty">${iconHtml('inbox')}<p>${text}</p></div>`;}
async function refresh(){const res=await api('admin.data',{token});data=res.data||data;if(!reviewClass&&data.classes.length)reviewClass=data.classes[0].classId;if(!reviewStudent&&data.students.length)reviewStudent=data.students[0].studentId;}
function renderView(){const el=$('#content');if(!el)return;switch(view){case'dashboard':el.innerHTML=dashboardView();break;case'assign':el.innerHTML=assignView();break;case'live-test':el.innerHTML=liveTestView();break;case'game-builder':el.innerHTML=gameBuilderView();break;case'question-bank':el.innerHTML=questionBankView();break;case'generator':el.innerHTML=generatorView();break;case'game-guide':el.innerHTML=gameGuideView();break;case'classes':el.innerHTML=classesView();break;case'students':el.innerHTML=studentsView();break;case'materials':el.innerHTML=materialsView();break;case'class-review':el.innerHTML=classReviewView();break;case'student-review':el.innerHTML=studentReviewView();break;case'settings':el.innerHTML=settingsView();break;}}
function dashboardView(){
 const finished=data.attempts.length,students=data.students.length,active=data.assignments.filter(a=>a.status==='published').length,materials=data.materials.length;
 const latest=[...data.attempts].sort((a,b)=>new Date(b.finishedAt||b.createdAt)-new Date(a.finishedAt||a.createdAt)).slice(0,6);
 const stats=GAME_TEMPLATES.map(t=>{const mats=data.materials.filter(m=>!(m.templateTypes||[]).length||(m.templateTypes||[]).includes(t.id));const asgs=data.assignments.filter(a=>a.templateId===t.id);const ats=data.attempts.filter(a=>a.templateId===t.id);return {...t,materialCount:mats.length,assignCount:asgs.length,published:asgs.filter(a=>a.status==='published').length,attemptCount:ats.length,materials:mats};});
 const used=stats.filter(x=>x.assignCount>0).length;
 return `${sectionHead('Dashboard','Ringkasan operasional dan performa 34 template game JEC.')}
 <div class="grid stats-grid">${stat('Total siswa',students,'school',`${data.classes.length} kelas terdaftar`)}${stat('Materi aktif',materials,'menu_book','Bank materi dan soal')}${stat('Game di-assign',active,'sports_esports','Assignment terpublikasi')}${stat('Sesi bermain',finished,'monitoring','Total attempt tersimpan')}</div>
 <div class="card card-pad" style="margin-top:16px"><div class="row between"><div><strong>📊 Statistik 34 template game</strong><p class="small muted">Pantau berapa materi yang kompatibel, assignment, game aktif, dan sesi bermain untuk setiap template.</p></div><span class="pill">${used}/34 sudah pernah di-assign</span></div><div class="progress" style="margin:10px 0 14px"><span style="width:${Math.round(used/34*100)}%"></span></div><details class="template-stats"><summary><strong>Lihat seluruh statistik template</strong><span class="small muted">${GAME_TEMPLATES.length} template · klik untuk buka/tutup</span></summary><div class="template-stat-list">${stats.map(t=>`<details class="template-stat-item"><summary><span class="template-stat-name"><span class="material-symbols-rounded">${esc(t.icon)}</span><strong>${esc(t.name)}</strong></span><span class="template-stat-numbers"><b>${t.materialCount}</b><small>materi</small><b>${t.assignCount}</b><small>assign</small><b>${t.attemptCount}</b><small>attempt</small></span></summary><div class="small muted" style="padding:8px 12px 12px">${t.materials.length?t.materials.slice(0,8).map(m=>esc(m.title)).join(' · '):'Belum ada materi yang direkomendasikan untuk template ini.'}<br>Assignment aktif: ${t.published} · Total sesi: ${t.attemptCount}</div></details>`).join('')}</div></details></div>
 <div class="panel-grid" style="margin-top:16px"><div class="card card-pad"><div class="row between"><div><strong>Aktivitas terbaru</strong><div class="small muted">Hasil permainan terakhir</div></div><button class="btn btn-ghost" data-view="class-review">Lihat review</button></div>${latest.length?latest.map(a=>{const st=data.students.find(x=>x.studentId===a.studentId);const m=data.materials.find(x=>x.materialId===a.materialId);return `<div class="list-row"><div class="avatar">${esc((st?.name||a.studentId||'?').slice(0,1))}</div><div class="grow"><strong>${esc(st?.name||a.studentId)} · ${esc(m?.title||'Game')}</strong><small>${esc(a.templateId||'')} · ${timeShort(a.finishedAt||a.createdAt)}</small></div><span class="pill">${Number(a.score)||0}/${Number(a.maxScore)||0}</span></div>`}).join(''):empty('Belum ada hasil bermain.')}</div><div class="card card-pad"><strong>Ringkasan kelas</strong><p class="small muted">Perbandingan siswa, assignment, dan aktivitas per kelas.</p>${data.classes.length?data.classes.map(c=>{const n=data.students.filter(st=>st.classId===c.classId).length,asg=data.assignments.filter(a=>a.classId===c.classId&&a.status==='published').length,att=data.attempts.filter(a=>a.classId===c.classId).length;return `<div class="list-row"><div class="avatar blue">${esc(c.classId)}</div><div class="grow"><strong>${esc(c.name||'Kelas '+c.classId)}</strong><small>${n} siswa · ${asg} game aktif · ${att} sesi</small></div><span class="pill">${c.classId}</span></div>`}).join(''):empty('Belum ada kelas.')}</div></div>
 <div class="card card-pad" style="margin-top:16px"><strong>Mulai cepat</strong><p class="small muted">Akses pekerjaan yang sering dilakukan.</p><div class="toolbar"><button class="btn btn-primary" data-action="open-class-modal">${iconHtml('add')} Buat kelas + siswa</button><button class="btn btn-secondary" data-view="question-bank">${iconHtml('quiz')} Question bank</button><button class="btn btn-secondary" data-view="generator">${iconHtml('auto_awesome')} Generator soal</button><button class="btn btn-secondary" data-view="assign">${iconHtml('send')} Assign game</button><button class="btn btn-ghost" data-view="live-test">${iconHtml('play_circle')} Live test</button></div></div>`;
}
function questionBankView(){
 const options=data.materials.map(m=>`<option value="${esc(m.materialId)}">${esc(m.title)} · ${esc(m.grade||'')}</option>`).join('');
 return `${sectionHead('Question Bank','Satu bank materi dapat dipakai ulang oleh banyak template game.',`<button class="btn btn-secondary" data-view="generator">${iconHtml('auto_awesome')} Generator soal</button>`)}<div class="panel-grid"><div class="card card-pad"><strong>Bulk import vocabulary / Word list</strong><p class="small muted">Satu baris satu kosakata. Kolom: <b>en, id, level, grade, category, topic</b>. Dukung pemisah koma, tab, atau |.</p><form id="bank-import-form"><div class="field"><label>Simpan ke materi</label><select id="bank-target"><option value="__new__">Buat materi baru</option>${options}</select></div><div class="field"><label>Format input</label><select id="bank-format"><option value="vocabulary">Vocabulary EN–ID</option><option value="custom">Custom Q&amp;A (prompt, answer, options)</option></select></div><div class="form-grid"><div class="field"><label>Judul materi baru</label><input id="bank-title" value="Vocabulary Set" placeholder="Animals Vocabulary"></div><div class="field"><label>Grade</label><input id="bank-grade" value="Grade 2–3" placeholder="Grade 2–3 SD"></div><div class="field"><label>Level</label><select id="bank-level">${['Pre-A1','A1','A2','B1','Easy','Medium','Hard'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Kategori</label><select id="bank-category">${['Vocabulary','Grammar','Speaking','Listening','Reading','Writing','Mixed'].map(x=>`<option>${x}</option>`).join('')}</select></div></div><div class="field"><label>Data bulk</label><textarea id="bank-rows" style="min-height:190px;font-family:monospace" placeholder="en,id,level,grade,category,topic&#10;rice,nasi,easy,Grade 2,vocabulary,food&#10;apple,apel,easy,Grade 2,vocabulary,food&#10;beautiful,cantik,medium,Grade 4,vocabulary,adjective"></textarea><span class="field-hint">Vocabulary: en,id,level,grade/category/topic. Custom Q&amp;A: prompt,answer,options (pisahkan pilihan dengan |),category,level,grade,topic,points.</span></div><div class="row wrap"><button class="btn btn-primary" type="submit">Import ke Question Bank</button><button class="btn btn-ghost" type="button" data-action="bank-sample">Isi contoh</button></div></form></div><div class="card card-pad"><strong>Materi di bank</strong><p class="small muted">Materi menjadi sumber soal bersama. Pilih edit untuk melihat dan mengubah JSON secara lengkap.</p>${data.materials.length?data.materials.map(m=>`<div class="list-row"><div class="avatar blue">${iconHtml('menu_book')}</div><div class="grow"><strong>${esc(m.title)}</strong><small>${esc(m.grade||'')} · ${esc(m.level||'')} · ${esc(m.category||'')} · ${materialQuestions(m).length} soal</small></div><button class="icon-btn" data-action="edit-material" data-id="${esc(m.materialId)}">${iconHtml('edit')}</button></div>`).join(''):empty('Belum ada materi.')}</div></div><div class="notice" style="margin-top:14px"><b>Tips:</b> gunakan satu materi untuk banyak game, misalnya Match up, Flash cards, Quiz, Spell the word, dan Wordsearch. Jika bank berisi pasangan EN–ID, game akan membaca pasangan tersebut sebagai sumber latihan kosakata.</div>`;
}
function generatorView(){return `${sectionHead('Generator Soal','Buat variasi drilling dari daftar vocabulary tanpa menulis JSON manual.')}<div class="card card-pad"><form id="generator-form"><div class="form-grid"><div class="field"><label>Judul paket soal</label><input id="gen-title" value="Generated Vocabulary Practice" required></div><div class="field"><label>Grade / Kelas</label><input id="gen-grade" value="Grade 2–3" required></div><div class="field"><label>Level</label><select id="gen-level">${['Pre-A1','A1','A2','B1','Easy','Medium','Hard'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Kategori</label><select id="gen-category">${['Vocabulary','Grammar','Reading','Writing','Speaking','Listening'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field span-2"><label>Jenis generator</label><select id="gen-mode"><option value="mixed">Universal EN–ID drilling — bank dapat dipakai lintas template</option><option value="mcq">English → Indonesian (multiple choice)</option><option value="reverse">Indonesian → English (typing)</option><option value="spelling">Spelling practice</option><option value="sentence">Complete the meaning</option></select></div></div><div class="field"><label>Daftar kata (EN, ID, level, grade, category)</label><textarea id="gen-rows" required style="min-height:220px;font-family:monospace" placeholder="rice,nasi,easy,Grade 2,vocabulary,food&#10;apple,apel,easy,Grade 2,vocabulary,food&#10;beautiful,cantik,medium,Grade 4,vocabulary,adjective"></textarea></div><div class="row wrap"><button class="btn btn-primary" type="submit">Generate & simpan sebagai materi</button><button class="btn btn-ghost" type="button" data-action="generator-sample">Isi contoh data</button></div></form></div><div class="notice" style="margin-top:14px"><b>Wayground-style workflow:</b> soal yang diekspor dari Wayground/Quizizz dapat ditempel setelah disesuaikan ke format EN–ID atau Custom Q&amp;A di Question Bank. Generator ini membuat variasi latihan berbasis aturan JEC, bukan terhubung langsung ke API Wayground.</div><div class="card card-pad" style="margin-top:14px"><strong>Alur generator</strong><div class="grid stats-grid" style="margin-top:10px"><div class="card stat"><div class="stat-top">1 · Input</div><div class="stat-value">EN–ID</div><div class="small muted">Kata dan arti</div></div><div class="card stat"><div class="stat-top">2 · Generate</div><div class="stat-value">Auto</div><div class="small muted">Prompt, jawaban, distractor</div></div><div class="card stat"><div class="stat-top">3 · Save</div><div class="stat-value">Bank</div><div class="small muted">Materi siap dipakai</div></div><div class="card stat"><div class="stat-top">4 · Assign</div><div class="stat-value">Play</div><div class="small muted">Pilih template dan kelas</div></div></div></div>`;}
function gameBuilderView(){return `${sectionHead('Game Builder','Rakit game dari materi yang sudah ada, uji langsung, lalu teruskan ke wizard assignment.')}<div class="card card-pad"><form id="builder-form"><div class="form-grid"><div class="field"><label>Sumber materi</label><select id="builder-material">${data.materials.map(m=>`<option value="${esc(m.materialId)}">${esc(m.title)} · ${esc(m.grade||'')}</option>`).join('')}</select></div><div class="field"><label>Template game</label><select id="builder-template">${GAME_TEMPLATES.map(t=>`<option value="${t.id}">${esc(t.name)} · ${esc(t.category)}</option>`).join('')}</select></div><div class="field span-2"><label>Judul game</label><input id="builder-title" placeholder="Contoh: Food Vocabulary Challenge"></div><div class="field span-2"><label>Instruksi siswa</label><textarea id="builder-instructions" placeholder="Read carefully, have fun, and try your best!"></textarea></div></div><div class="notice">Game Builder menggabungkan satu bank materi dengan satu template. Tidak perlu coding; uji coba dapat dilakukan sebelum memilih kelas tujuan.</div><div class="row wrap"><button class="btn btn-secondary" type="button" data-action="builder-preview">${iconHtml('play_circle')} Preview live</button><button class="btn btn-primary" type="button" data-action="builder-assign">Lanjut ke Assign Games ${iconHtml('arrow_forward')}</button></div></form></div><div class="card card-pad" style="margin-top:14px"><strong>Template siap dipakai</strong><div class="template-grid" style="margin-top:12px">${GAME_TEMPLATES.map(t=>`<div class="template-option"><span class="material-symbols-rounded">${esc(t.icon)}</span><span><strong>${esc(t.name)}</strong><small>${esc(t.description)}</small></span></div>`).join('')}</div></div>`;}
function liveTestView(){const m=data.materials.find(x=>x.materialId===liveTestState.materialId)||data.materials[0];const t=GAME_TEMPLATES.find(x=>x.id===liveTestState.templateId)||GAME_TEMPLATES[0];return `${sectionHead('Live Test Game','Uji semua template menggunakan bank soal JEC sebelum game di-assign ke siswa.')}<div class="card card-pad"><div class="form-grid"><div class="field"><label>Pilih materi</label><select id="live-material">${data.materials.map(x=>`<option value="${esc(x.materialId)}" ${(m?.materialId===x.materialId)?'selected':''}>${esc(x.title)} · ${esc(x.grade||'')}</option>`).join('')}</select></div><div class="field"><label>Template</label><select id="live-template">${GAME_TEMPLATES.map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div></div><div class="notice">${esc(t.description)} · ${materialQuestions(m).length} soal tersedia. Mode test tidak menyimpan attempt siswa.</div><div class="row wrap"><button class="btn btn-primary" data-action="start-live-test">${iconHtml('play_arrow')} Mulai live test</button><button class="btn btn-ghost" data-view="game-guide">${iconHtml('help')} Lihat panduan template</button></div></div><div class="card card-pad" style="margin-top:14px"><div class="row between"><strong>Game preview stage</strong><span class="pill">Admin sandbox · no student score</span></div><div class="game-stage" id="admin-live-mount"><div class="empty">Pilih materi dan template, lalu klik Mulai live test.</div></div></div>`;}
function gameGuideView(){const guide={
 'match-up':['Vocabulary / meaning','Pasangkan EN dengan ID menggunakan data en + id atau pairs.','en, id / pairs[]'],'quiz':['Vocabulary, grammar, reading','Pilih jawaban benar dari options; answer harus sama persis dengan salah satu pilihan.','prompt, answer, options[]'],'open-the-box':['Mixed review','Buka kotak terlebih dahulu, lalu jawab tantangan.','prompt, answer, options[]'],'unjumble':['Spelling / sentence building','Susun huruf atau kata acak menjadi jawaban yang benar.','answer / items[]'],'flash-cards':['Vocabulary / recall','Lihat sisi depan, balik kartu, lalu tandai tahu atau perlu latihan.','prompt (front), answer (back)'],'spin-the-wheel':['Mixed drilling','Putar roda untuk memunculkan soal acak; jawab setelah roda berhenti.','prompt, answer, options[]'],'find-the-match':['Vocabulary / matching','Temukan pasangan istilah dan arti; cocok untuk word pairs.','pairs[] atau en + id'],'group-sort':['Vocabulary / grammar categories','Pindahkan item ke kelompok yang sesuai.','groups[], items[{text,group}]'],'complete-the-sentence':['Grammar / writing','Lengkapi bagian kalimat yang kosong.','prompt, answer, hint'],'anagram':['Vocabulary / spelling','Susun ulang huruf untuk membentuk kata target.','answer, prompt/hint'],'gameshow-quiz':['Vocabulary / grammar / reading','Kuis pilihan ganda dengan ritme gameshow.','prompt, answer, options[]'],'speaking-cards':['Speaking / fluency','Kartu pemantik percakapan; siswa mencoba lisan dan guru dapat menilai.','prompt, answer/example (opsional)'],'wordsearch':['Vocabulary / spelling','Temukan kata target pada daftar kata.','words[] atau answer'],'maze-chase':['Vocabulary / quick recall','Pilih jalur/jawaban yang benar untuk mencapai finish.','prompt, answer, options[]'],'matching-pairs':['Vocabulary / memory','Buka/cocokkan pasangan kartu EN–ID.','pairs[] atau en + id'],'crossword':['Vocabulary / definitions','Jawab petunjuk kosakata dengan kata target.','clue/prompt, answer'],'labelled-diagram':['Vocabulary / parts','Cocokkan label dengan bagian diagram.','items[] atau prompt, answer'],'true-or-false':['Reading comprehension / facts','Nilai pernyataan sebagai True atau False.','prompt, answer: True/False'],'hangman':['Spelling / vocabulary','Tebak huruf hingga kata tersembunyi terbentuk.','answer'],'airplane':['Vocabulary / quick choice','Arahkan pesawat ke jawaban yang tepat.','prompt, answer, options[]'],'whack-a-mole':['Vocabulary / speed recognition','Pilih target yang tepat dengan cepat.','prompt, answer, options[]'],'balloon-pop':['Vocabulary / recognition','Pecahkan balon yang berisi jawaban benar.','prompt, answer, options[]'],'image-quiz':['Visual vocabulary','Jawab berdasarkan gambar yang disertakan.','image URL, prompt, answer, options[]'],'flip-tiles':['Memory / vocabulary','Balik ubin untuk mengingat dan menemukan jawaban.','pairs[] atau items[]'],'rank-order':['Sequencing / grammar','Urutkan kata, kalimat, atau langkah.','items[] dalam urutan benar'],'win-or-lose-quiz':['Mixed review','Jawab kuis untuk mengumpulkan poin bonus.','prompt, answer, options[]'],'watch-and-memorize':['Memory / vocabulary','Amati daftar item, sembunyikan, lalu ingat kembali.','items[] / options[]'],'word-magnets':['Spelling / sentence building','Susun huruf magnet menjadi kata atau frasa.','answer'],'flying-fruit':['Vocabulary / speed choice','Pilih buah/objek yang mewakili jawaban benar.','prompt, answer, options[]'],'maths-generator':['Math / English numeracy','Latihan operasi angka dengan instruksi berbahasa Inggris.','a, b, operator, answer'],'pair-or-no-pair':['Vocabulary / collocations','Putuskan dua item berpasangan atau tidak.','prompt, answer: Pair/No Pair'],'speed-sorting':['Vocabulary / categories','Kelompokkan beberapa item dengan batas waktu.','groups[], items[{text,group}]'],'spell-the-word':['Spelling / listening','Eja kata target dari clue atau arti.','prompt/hint, answer'],'type-the-answer':['Vocabulary / writing','Ketik terjemahan atau jawaban singkat.','prompt, answer']};
 return `${sectionHead('Panduan 34 Template Game','Pelajari tujuan drill dan format bank soal agar template benar-benar sesuai materi.')}${Object.entries({Vocabulary:['match-up','flash-cards','find-the-match','matching-pairs','wordsearch','image-quiz','balloon-pop','hangman','type-the-answer','spell-the-word','anagram'],Grammar:['complete-the-sentence','unjumble','word-magnets','rank-order','quiz','true-or-false'],Speaking:['speaking-cards','gameshow-quiz'],Reading:['quiz','true-or-false','crossword','open-the-box'],Memory:['watch-and-memorize','flip-tiles','spin-the-wheel'],SpeedAndArcade:['maze-chase','airplane','whack-a-mole','flying-fruit','speed-sorting','win-or-lose-quiz'],VisualAndOther:['labelled-diagram','group-sort','pair-or-no-pair','maths-generator']}).map(([group,ids])=>`<div class="card card-pad" style="margin-top:14px"><strong>${esc(group.replace('And',' & '))}</strong><div class="template-guide-grid">${ids.map(id=>{const t=GAME_TEMPLATES.find(x=>x.id===id),g=guide[id]||['General','Latihan ulang sesuai prompt dan answer.','prompt, answer'];return `<details class="template-guide-item"><summary><span class="material-symbols-rounded">${esc(t?.icon||'sports_esports')}</span><b>${esc(t?.name||id)}</b></summary><div class="small muted"><p><b>Fokus:</b> ${esc(g[0])}</p><p>${esc(g[1])}</p><p><b>Data soal:</b> <code>${esc(g[2])}</code></p></div></details>`}).join('')}</div></div>`).join('')}<div class="card card-pad" style="margin-top:14px"><strong>Format vocabulary universal</strong><p class="small muted">Satu baris per kata: <code>en,id,level,grade,category,topic</code>. Contoh: <code>rice,nasi,easy,Grade 2,vocabulary,food</code>. Dari bank ini JEC dapat memakai flashcard, quiz, pair matching, spelling, anagram, dan latihan typing.</p></div>`;
}
function splitDelimitedLine(line,delimiter){const out=[];let value='',quoted=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'){if(quoted&&line[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(ch===delimiter&&!quoted){out.push(value.trim());value='';}else value+=ch;}out.push(value.trim());return out.map(x=>x.replace(/^"|"$/g,''));}
function parseTableRows(raw){const lines=String(raw||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!lines.length)return[];const first=lines[0],delimiter=first.includes('\t')?'\t':first.includes('|')?'|':',';return lines.map(x=>splitDelimitedLine(x,delimiter));}
function parseBulkRows(raw){const matrix=parseTableRows(raw);if(!matrix.length)return[];const normHead=x=>String(x||'').toLowerCase().trim().replace(/[ _-]+/g,'');const first=matrix[0].map(normHead);const hasHeader=['en','english','word'].includes(first[0]);const aliases={en:['en','english','word'],id:['id','indonesian','meaning','arti','bahasaindonesia'],level:['level','difficulty'],grade:['grade','kelas','class'],category:['category','kategori','type'],topic:['topic','tema','unit'],group:['group','kelompok'],image:['image','gambar'],example:['example','contoh']};let rows=[];matrix.forEach((cols,i)=>{if(hasHeader&&i===0)return;let obj={};if(hasHeader){Object.entries(aliases).forEach(([key,names])=>{const idx=first.findIndex(h=>names.includes(h));if(idx>=0)obj[key]=cols[idx]||'';});}else{[obj.en,obj.id,obj.level,obj.grade,obj.category,obj.topic,obj.group,obj.image,obj.example]=cols;}obj.en=String(obj.en||'').trim();obj.id=String(obj.id||'').trim();if(!obj.en||!obj.id)return;rows.push({en:obj.en,id:obj.id,level:obj.level||'Easy',grade:obj.grade||'Grade 2–3',category:obj.category||'Vocabulary',topic:obj.topic||'General',group:obj.group||'',image:obj.image||'',example:obj.example||''});});return rows;}
function parseCustomQuestionRows(raw){const matrix=parseTableRows(raw);if(!matrix.length)return[];const heads=matrix[0].map(x=>String(x||'').toLowerCase().trim().replace(/[ _-]+/g,''));const hasHeader=['prompt','question','soal'].includes(heads[0]);return matrix.slice(hasHeader?1:0).map(cols=>{const get=(names,index)=>{const idx=hasHeader?heads.findIndex(h=>names.includes(h)):index;return idx>=0?String(cols[idx]||'').trim():'';};return{prompt:get(['prompt','question','soal'],0),answer:get(['answer','correctanswer','jawaban'],1),options:get(['options','choices','pilihan'],2).split(/[|;]/).map(x=>x.trim()).filter(Boolean),category:get(['category','kategori'],3)||'General',level:get(['level','difficulty'],4)||'Easy',grade:get(['grade','kelas','class'],5)||'Grade 2–3',topic:get(['topic','tema'],6)||'General',points:Number(get(['points','poin'],7))||10};}).filter(x=>x.prompt&&x.answer);}
function makeGeneratedQuestions(rows,mode='mixed'){
 return rows.map((r,i)=>({id:`VOC-${Date.now()}-${i+1}`,en:r.en,indonesian:r.id,translation:r.id,word:r.en,category:String(r.category||'Vocabulary').toLowerCase(),level:r.level,grade:r.grade,topic:r.topic,group:r.group||'',image:r.image||'',example:r.example||'',direction:mode==='reverse'?'id-en':'en-id',generatorMode:mode,points:10}));
}

function editAssignmentModal(a){
 const settings=a.settings||{};const material=data.materials.find(x=>x.materialId===a.materialId);
 const classOptions=data.classes.map(c=>`<option value="${esc(c.classId)}" ${a.classId===c.classId?'selected':''}>${esc(c.classId)} · ${esc(c.name||'')}</option>`).join('');
 const materialOptions=data.materials.map(m=>`<option value="${esc(m.materialId)}" ${a.materialId===m.materialId?'selected':''}>${esc(m.title)} · ${esc(m.grade||'')}</option>`).join('');
 const templateOptions=GAME_TEMPLATES.map(t=>`<option value="${esc(t.id)}" ${a.templateId===t.id?'selected':''}>${esc(t.name)} · ${esc(t.category)}</option>`).join('');
 openModal('Edit assignment',`<div class="notice">Edit penuh: kelas tujuan, materi, template, konten instruksi, timer, percobaan, deadline, dan status dapat diubah.</div><div class="form-grid"><div class="field"><label>Kelas tujuan</label><select name="classId">${classOptions}</select></div><div class="field"><label>Materi</label><select name="materialId">${materialOptions}</select></div><div class="field span-2"><label>Template game</label><select name="templateId">${templateOptions}</select></div><div class="field span-2"><label>Judul assignment</label><input name="title" value="${esc(a.title||'')}" required></div><div class="field span-2"><label>Instruksi siswa</label><textarea name="instructions">${esc(a.instructions||'')}</textarea></div><div class="field"><label>Batas waktu (menit)</label><input name="timeLimit" type="number" min="0" value="${Number(settings.timeLimit)||0}"></div><div class="field"><label>Maksimal percobaan</label><input name="attempts" type="number" min="0" value="${Number(settings.attempts??0)}"><span class="field-hint">0 = unlimited.</span></div><div class="field"><label>Deadline</label><input name="dueAt" type="date" value="${esc(a.dueAt||'')}"></div><div class="field"><label>Status</label><select name="status"><option value="published" ${a.status==='published'?'selected':''}>Published</option><option value="draft" ${a.status==='draft'?'selected':''}>Draft</option></select></div></div><label class="row"><input type="checkbox" name="shuffle" ${settings.shuffle!==false?'checked':''}> Acak soal dan pilihan</label>`, 'Simpan perubahan');
 modalSubmit=async form=>{const fd=new FormData(form);const v=Object.fromEntries(fd.entries());await api('assign.update',{token,assignmentId:a.assignmentId,data:{classId:v.classId,materialId:v.materialId,templateId:v.templateId,title:v.title,instructions:v.instructions,dueAt:v.dueAt,status:v.status,settings:{timeLimit:Number(v.timeLimit)||0,attempts:Math.max(0,Number(v.attempts)||0),shuffle:fd.has('shuffle')}}});toast('Assignment berhasil diperbarui.');closeModal();await refreshAndRender();};
}
async function launchAdminLiveTest(returnView='live-test'){
 const material=data.materials.find(x=>x.materialId===liveTestState.materialId)||data.materials[0];const tmpl=GAME_TEMPLATES.find(x=>x.id===liveTestState.templateId)||GAME_TEMPLATES[0];if(!material){toast('Buat atau import materi terlebih dahulu.','info');return;}liveTestReturn=returnView;view='live-test';renderView();const mount=$('#admin-live-mount');if(!mount)return;mount.innerHTML='<div class="empty">Menyiapkan game preview...</div>';try{const mod=await tmpl.load();liveTestGame?.destroy();liveTestGame=mod.mount({mount,material,settings:{shuffle:false,timeLimit:0},templateName:`LIVE TEST · ${tmpl.name}`,onFinish:result=>{liveTestGame?.destroy();liveTestGame=null;mount.innerHTML=`<div class="game-result"><div style="font-size:52px">🧪</div><h2>Live test selesai</h2><div class="score">${Number(result.score)||0}</div><p class="muted">${result.correct}/${result.total} benar · ${result.durationSec} detik · hasil ini tidak disimpan.</p><div class="row wrap" style="justify-content:center"><button class="btn btn-primary" data-action="retry-live-test">Uji ulang</button><button class="btn btn-ghost" data-action="live-test-back">Kembali ke ${esc(liveTestReturn==='game-builder'?'Game Builder':'Live Test')}</button></div></div>`;}});}catch(e){mount.innerHTML=`<div class="notice warn">Game tidak dapat dimuat: ${esc(e.message)}</div>`;}
}
